import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {Stack} from '@primer/react'
import {licenseComplianceAlertsRoute} from './license-compliance-alerts-route'
import {AlertRow} from '../components/AlertRow'

export function LicenseComplianceAlerts() {
  const payload = useRouteQuery(licenseComplianceAlertsRoute, 'mainQuery')
  const alerts = payload.data.alerts || []

  return (
    <Stack>
      <Stack direction="horizontal" gap="condensed" align="center" className="pb-2 border-bottom">
        <h1 data-hpc className="mb-0">
          License compliance alert requests
        </h1>
        <BetaLabel />
      </Stack>
      <span className="color-fg-muted">View all requests to bypass the license policy across your organization.</span>
      {alerts.length === 0 ? (
        <p>No bypass requests found.</p>
      ) : (
        <Stack className="px-3 border rounded-2" direction="vertical" gap="none">
          {alerts.map((alert, index) => (
            <AlertRow key={alert.number} alert={alert} isLast={index === alerts.length - 1} />
          ))}
        </Stack>
      )}
    </Stack>
  )
}

try{ LicenseComplianceAlerts.displayName ||= 'LicenseComplianceAlerts' } catch {}