import {AlertEventType, type AlertEvent} from '../../types/alerts'
import {OpenedEvent} from './events/OpenedEvent'
import {AppearedInBranchEvent} from './events/AppearedInBranchEvent'
import {ReviewRequestedEvent} from './events/ReviewRequestedEvent'
import {ReviewDeniedEvent} from './events/ReviewDeniedEvent'
import {ReviewApprovedEvent} from './events/ReviewApprovedEvent'
import {ExceptionAddedEvent} from './events/ExceptionAddedEvent'
import {LicensesAddedEvent} from './events/LicensesAddedEvent'
import {ClosedEvent} from './events/ClosedEvent'

interface TimelineEventItemProps {
  event: AlertEvent
  onReviewRequest?: () => void
  repoLicensePolicyPath?: string
  repoName?: string
}

export function TimelineEventItem({event, onReviewRequest, repoLicensePolicyPath, repoName}: TimelineEventItemProps) {
  switch (event.type) {
    case AlertEventType.Opened:
      return <OpenedEvent event={event} />

    case AlertEventType.AppearedInBranch:
      return <AppearedInBranchEvent event={event} />

    case AlertEventType.ReviewRequested:
      return <ReviewRequestedEvent event={event} onReviewRequest={onReviewRequest} />

    case AlertEventType.ReviewDenied:
      return <ReviewDeniedEvent event={event} />

    case AlertEventType.ReviewApproved:
      return <ReviewApprovedEvent event={event} />

    case AlertEventType.ExceptionAdded:
      return <ExceptionAddedEvent event={event} repoLicensePolicyPath={repoLicensePolicyPath} repoName={repoName} />

    case AlertEventType.LicensesAdded:
      return <LicensesAddedEvent event={event} repoLicensePolicyPath={repoLicensePolicyPath} repoName={repoName} />

    case AlertEventType.Closed:
      return <ClosedEvent event={event} />

    default:
      // Don't render unknown event types
      return null
  }
}

try{ TimelineEventItem.displayName ||= 'TimelineEventItem' } catch {}