import type {Alert} from '../types/alerts'
import {Stack, Link} from '@primer/react'
import {clsx} from 'clsx'

export interface AlertRowProps {
  alert: Alert
  isLast: boolean
}

export function AlertRow({alert, isLast}: AlertRowProps) {
  return (
    <Stack direction="vertical" gap="none" className={clsx('py-3', !isLast && 'border-bottom')} justify="space-between">
      <Link href={alert.link} className="f4 text-semibold fgColor-default">
        Non-compliant license expression on {alert.packageName}
      </Link>
      <span className="color-fg-muted">#{alert.number}</span>
    </Stack>
  )
}

try{ AlertRow.displayName ||= 'AlertRow' } catch {}