import {mainQuery} from '@github-ui/react-core/future/main-query'
import {licenseComplianceAlertsAppBuilder} from '../config/app-builder'
import type {Alert} from '../types/alerts'

export type LicenseComplianceAlertResponse = {
  alert: Alert
  enterpriseName: string
  enterpriseLicenseAlertsPath?: string
  repoLicensePolicyPath?: string
  permissions: {
    canManageEnterpriseLicensePolicy: boolean
    canWriteRepo: boolean
  }
}

export const licenseComplianceAlertRoute = licenseComplianceAlertsAppBuilder.createQueryRouteConfig(
  'licenseComplianceAlertRoute',
  {
    path: '/:owner/:repo/security/license-compliance-scanning-alerts/:number',
    queries: [mainQuery<LicenseComplianceAlertResponse>()],
  },
)
