import {AlertStatus} from '../types/alerts'

/**
 * Transforms an AlertStatus into a human-readable string.
 *
 * @param status The status of the alert.
 * @returns A capitalized, human-readable version of the status.
 */
export function formatAlertStatus(status: AlertStatus): string {
  return status === AlertStatus.Closed ? 'Fixed' : 'Open'
}
