import {FormControl, RadioGroup, Radio, Stack, Textarea} from '@primer/react'
import {REVIEW_DENY, REVIEW_APPROVE} from './constants'

interface ReviewRequestFormProps {
  comment: string
  onCommentChange: (event: React.ChangeEvent<HTMLTextAreaElement>) => void
  commentError: string
  reviewChoice: string | null
  onReviewChoiceChange: (value: string | null) => void
  reviewChoiceError: string
}

export function ReviewRequestForm({
  comment,
  onCommentChange,
  commentError,
  reviewChoice,
  onReviewChoiceChange,
  reviewChoiceError,
}: ReviewRequestFormProps) {
  return (
    <Stack direction="vertical">
      <FormControl required>
        <FormControl.Label>Comment</FormControl.Label>
        <Textarea
          block
          value={comment}
          onChange={onCommentChange}
          placeholder="Feedback to go with your review..."
          rows={3}
          resize="vertical"
        />
        {commentError && <FormControl.Validation variant="error">{commentError}</FormControl.Validation>}
      </FormControl>
      <RadioGroup name="reviewChoice" onChange={onReviewChoiceChange}>
        <RadioGroup.Label visuallyHidden>Review Decision</RadioGroup.Label>
        <FormControl>
          <Radio checked={reviewChoice === REVIEW_DENY} value={REVIEW_DENY} />
          <FormControl.Label>Deny request</FormControl.Label>
          <FormControl.Caption>Submit feedback on why the package or license is not allowed</FormControl.Caption>
        </FormControl>
        <FormControl>
          <Radio checked={reviewChoice === REVIEW_APPROVE} value={REVIEW_APPROVE} />
          <FormControl.Label>Update policy and approve request</FormControl.Label>
          <FormControl.Caption>
            Submit feedback and update existing policy to allow the package or license
          </FormControl.Caption>
        </FormControl>
        {reviewChoiceError && <RadioGroup.Validation variant="error">{reviewChoiceError}</RadioGroup.Validation>}
      </RadioGroup>
    </Stack>
  )
}

try{ ReviewRequestForm.displayName ||= 'ReviewRequestForm' } catch {}