import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useParams} from '@github-ui/react-router'
import {licenseComplianceAlertRoute} from './license-compliance-alert-route'
import {AlertStatus} from '../types/alerts'
import {Heading, PageLayout, Breadcrumbs, Banner, Button, Stack} from '@primer/react'
import {clsx} from 'clsx'
import styles from './LicenseComplianceAlert.module.css'
import {LicenseComplianceAlertDescription} from '../components/LicenseComplianceAlertDescription'
import {LicenseComplianceAlertStatus} from '../components/LicenseComplianceAlertStatus'
import {AlertRemediationDialog} from '../components/AlertRemediationDialog/AlertRemediationDialog'
import {LicenseComplianceAlertSidePane} from '../components/LicenseComplianceAlertSidePane'
import {AlertTimeline} from '../components/timeline/AlertTimeline'
import {useMemo, useState} from 'react'
import {useRequestDismissalMutation} from '../hooks/use-alert-update-mutation'

export function LicenseComplianceAlert() {
  const {
    data: {alert, enterpriseLicenseAlertsPath, repoLicensePolicyPath, permissions},
  } = useRouteQuery(licenseComplianceAlertRoute, 'mainQuery')
  const {canManageEnterpriseLicensePolicy, canWriteRepo} = permissions

  const {owner, repo, number} = useParams<{
    owner: string
    repo: string
    number: string
  }>()

  const [bannerMessage, setBannerMessage] = useState('')
  const [isRemediationModalOpen, setIsRemediationModalOpen] = useState(false)

  const showRequestDismissalButton = useMemo(() => {
    if (alert.status !== AlertStatus.Open) return false
    if (canManageEnterpriseLicensePolicy && canWriteRepo) return false
    return canWriteRepo
  }, [alert.status, canManageEnterpriseLicensePolicy, canWriteRepo])

  const showRemediationModalHeaderButton = useMemo(() => {
    if (alert.status === AlertStatus.Closed || alert.status === AlertStatus.ReviewRequested) return false
    return canManageEnterpriseLicensePolicy
  }, [alert.status, canManageEnterpriseLicensePolicy])

  const showRemediationModalTimelineButton = useMemo(() => {
    return alert.status === AlertStatus.ReviewRequested && canManageEnterpriseLicensePolicy
  }, [alert.status, canManageEnterpriseLicensePolicy])

  const renderBreadcrumbs = () => (
    <Breadcrumbs>
      <Breadcrumbs.Item href={enterpriseLicenseAlertsPath}>License compliance alerts</Breadcrumbs.Item>
      <Breadcrumbs.Item className="fgColor-muted" selected>
        #{alert.number}
      </Breadcrumbs.Item>
    </Breadcrumbs>
  )

  const dismissalMutation = useRequestDismissalMutation({
    owner: owner as string,
    repo: repo as string,
    number: number as string,
    onError: setBannerMessage,
  })

  return (
    <PageLayout rowGap="condensed">
      <PageLayout.Header>
        {bannerMessage && (
          <Banner
            className="mb-3"
            variant="warning"
            title="failed to update alert"
            hideTitle
            description={bannerMessage}
          />
        )}
        {renderBreadcrumbs()}
        <Stack className="mt-3" direction="horizontal" justify="space-between" align="center" gap="spacious">
          <Heading as="h1" variant="large" className={clsx('f1-light', styles.heading)}>
            {`Non-compliant license expression found on ${alert.packageName} `}
            <span className="fgColor-muted">#{alert.number}</span>
          </Heading>
          {showRequestDismissalButton && (
            <Button
              data-testid="request-dismissal-button"
              onClick={() => dismissalMutation.mutate()}
              loading={dismissalMutation.isPending}
              disabled={dismissalMutation.isPending}
            >
              Close alert
            </Button>
          )}
          {showRemediationModalHeaderButton && (
            <Button data-testid="open-remediation-modal-header-button" onClick={() => setIsRemediationModalOpen(true)}>
              Close alert
            </Button>
          )}
        </Stack>
        <LicenseComplianceAlertStatus
          createdAt={alert.createdAt}
          manifestName={alert.manifestName}
          packageEcosystem={alert.packageEcosystem}
          packageName={alert.packageName}
          status={alert.status}
        />
      </PageLayout.Header>
      <PageLayout.Content as="div">
        <LicenseComplianceAlertDescription
          license={alert.license}
          packageEcosystem={alert.packageEcosystem}
          packageName={alert.packageName}
          packageVersion={alert.packageVersion}
        />
        {isRemediationModalOpen && (
          <AlertRemediationDialog
            alert={alert}
            onClose={() => setIsRemediationModalOpen(false)}
            onError={setBannerMessage}
            owner={owner as string}
            repo={repo as string}
          />
        )}
        {alert.events && alert.events.length > 0 && (
          <AlertTimeline
            events={alert.events}
            onReviewRequest={showRemediationModalTimelineButton ? () => setIsRemediationModalOpen(true) : undefined}
            repoLicensePolicyPath={repoLicensePolicyPath}
            repoName={repo}
          />
        )}
      </PageLayout.Content>
      <PageLayout.Pane className={styles.sidePane}>
        <LicenseComplianceAlertSidePane repoLicensePolicyPath={repoLicensePolicyPath} />
      </PageLayout.Pane>
    </PageLayout>
  )
}

try{ LicenseComplianceAlert.displayName ||= 'LicenseComplianceAlert' } catch {}