import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {licenseComplianceAlertsAppBuilder} from './config/app-builder'

import {licenseComplianceAlertRoute} from './routes/license-compliance-alert-route'
import {licenseComplianceAlertsRoute} from './routes/license-compliance-alerts-route'
import {LicenseComplianceAlert} from './routes/LicenseComplianceAlert'
import {LicenseComplianceAlerts} from './routes/LicenseComplianceAlerts'

export const licenseComplianceAlertsApp = licenseComplianceAlertsAppBuilder.createDataRouterAppFromRoutes([
  licenseComplianceAlertRoute.toRoute({Component: LicenseComplianceAlert}),
  licenseComplianceAlertsRoute.toRoute({Component: LicenseComplianceAlerts}),
])
registerDataRouterApp(licenseComplianceAlertsApp)
