import {useState} from 'react'
import {ArrowLeftIcon} from '@primer/octicons-react'
import {Button, Dialog, Stack, Text} from '@primer/react'
import {AlertStatus, type Alert} from '../../types/alerts'
import {PackageAction, PolicyLevel} from '../../types/policies'
import styles from './AlertRemediationDialog.module.css'
import {ReviewRequestForm} from './ReviewRequestForm'
import {PolicyUpdateForm} from './PolicyUpdateForm'
import {useAlertRemediationMutations} from './use-alert-remediation-mutations'
import {REVIEW_APPROVE, AMENDMENT_PACKAGE, AMENDMENT_PACKAGE_WILDCARD} from './constants'

interface AlertRemediationDialogProps {
  alert: Alert
  onClose: () => void
  onError: (error: string) => void
  owner: string
  repo: string
}

export function AlertRemediationDialog({alert, onClose, onError, owner, repo}: AlertRemediationDialogProps) {
  const showPage0 = alert.status === AlertStatus.ReviewRequested

  // Page index starting at 0 for easier dialogCopyByPage array lookup
  const [currentPage, setCurrentPage] = useState(showPage0 ? 0 : 1)
  const [comment, setComment] = useState('')
  const [commentError, setCommentError] = useState('')
  const [reviewChoice, setReviewChoice] = useState<string | null>(showPage0 ? null : REVIEW_APPROVE)
  const [reviewChoiceError, setReviewChoiceError] = useState('')
  const [amendment, setAmendment] = useState(AMENDMENT_PACKAGE)
  const [scope, setScope] = useState<string>(PolicyLevel.Repository)
  const [wildcardPattern, setWildcardPattern] = useState(`${alert.packageName}*`)
  const [wildcardValidationError, setWildcardValidationError] = useState('')

  const mutations = useAlertRemediationMutations({
    owner,
    repo,
    alertNumber: alert.number.toString(),
    onError,
    onSettled: onClose,
  })

  const handleCommentChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    setComment(event.target.value)
  }

  const handleReviewChoiceChange = (value: string | null) => {
    setReviewChoice(value)
  }

  const validatePage0Inputs = () => {
    setCommentError('')
    setReviewChoiceError('')

    let hasError = false
    if (!comment.trim()) {
      setCommentError('Comment on review is required')
      hasError = true
    }
    if (!reviewChoice) {
      setReviewChoiceError('Review decision is required')
      hasError = true
    }

    return hasError
  }

  const handleWildcardChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setWildcardPattern(event.target.value)
  }

  const validatePage1Inputs = () => {
    setWildcardValidationError('')

    if (amendment === AMENDMENT_PACKAGE_WILDCARD) {
      const pattern = wildcardPattern.trim()

      // At least 2 non-* characters
      const nonAsteriskCount = pattern.replace(/\*/g, '').length
      if (nonAsteriskCount < 2) {
        setWildcardValidationError('Pattern must contain at least 2 non-* characters')
        return true
      }

      // Only one * allowed
      const asteriskCount = (pattern.match(/\*/g) || []).length
      if (asteriskCount > 1) {
        setWildcardValidationError('Pattern can only contain one * character')
        return true
      }

      // Pattern must address the packageName
      try {
        const regexPattern = pattern.replace(/\*/g, '.*')
        const regex = new RegExp(`^${regexPattern}$`)

        if (!regex.test(alert.packageName)) {
          setWildcardValidationError(`Pattern must match the package name "${alert.packageName}"`)
          return true
        }
      } catch {
        setWildcardValidationError('Invalid regex pattern')
        return true
      }
    }

    return false
  }

  const handleSubmitPage0 = () => {
    const hasError = validatePage0Inputs()
    if (hasError) return
    if (reviewChoice === REVIEW_APPROVE) {
      setCurrentPage(1)
      return
    }

    mutations.denyRequestMutation.mutate(comment)
  }

  const handleSubmitPage1 = () => {
    const hasError = validatePage1Inputs()
    if (hasError) return

    if (amendment === AMENDMENT_PACKAGE || amendment === AMENDMENT_PACKAGE_WILDCARD) {
      mutations.createExceptionMutation.mutate({
        comment,
        policyLevel: scope as PolicyLevel,
        packageAction: amendment === AMENDMENT_PACKAGE ? PackageAction.Allowed : PackageAction.Private,
        pattern: amendment === AMENDMENT_PACKAGE ? '' : wildcardPattern,
      })
    } else {
      mutations.addLicensesForAlertMutation.mutate({comment, policyLevel: scope as PolicyLevel})
    }
  }

  const handleSubmit = () => {
    if (currentPage === 0) {
      handleSubmitPage0()
      return
    }

    handleSubmitPage1()
  }

  const dialogCopyByPage = [
    {
      title: 'Review Request',
      buttonText: reviewChoice === REVIEW_APPROVE ? 'Update policy' : 'Submit review',
    },
    {
      title: (
        <Stack direction="horizontal" gap="none">
          {showPage0 && (
            <Button
              data-testid="back-button"
              aria-label="Back to review request"
              className={styles.backButton}
              variant="invisible"
              onClick={() => setCurrentPage(0)}
            >
              <ArrowLeftIcon size={16} />
            </Button>
          )}
          <Stack direction="vertical" className="pt-1">
            Create policy update
            <Text size="small" weight="normal" className="fgColor-muted lh-default pt-1">
              Complete license request approval by updating the policy
            </Text>
          </Stack>
        </Stack>
      ),
      buttonText: 'Create update',
    },
  ]

  return (
    <Dialog
      onClose={onClose}
      title={dialogCopyByPage[currentPage]?.title}
      footerButtons={[
        {
          buttonType: 'primary',
          content: dialogCopyByPage[currentPage]?.buttonText,
          onClick: handleSubmit,
          loading: mutations.isLoading,
        },
      ]}
    >
      {currentPage === 0 && (
        <ReviewRequestForm
          comment={comment}
          onCommentChange={handleCommentChange}
          commentError={commentError}
          reviewChoice={reviewChoice}
          onReviewChoiceChange={handleReviewChoiceChange}
          reviewChoiceError={reviewChoiceError}
        />
      )}
      {currentPage === 1 && (
        <PolicyUpdateForm
          alert={alert}
          owner={owner}
          repo={repo}
          amendment={amendment}
          onAmendmentChange={setAmendment}
          scope={scope}
          onScopeChange={setScope}
          wildcardPattern={wildcardPattern}
          onWildcardChange={handleWildcardChange}
          wildcardValidationError={wildcardValidationError}
        />
      )}
    </Dialog>
  )
}

try{ AlertRemediationDialog.displayName ||= 'AlertRemediationDialog' } catch {}