import {ShieldIcon} from '@primer/octicons-react'
import type {AlertEvent, OpenedEventBody} from '../../../types/alerts'
import {TimelineEventWithActor, parseEventBody} from './shared'

interface OpenedEventProps {
  event: AlertEvent
}

export function OpenedEvent({event}: OpenedEventProps) {
  const openedInfo = parseEventBody<OpenedEventBody>(event.eventBody)

  return (
    <TimelineEventWithActor
      event={event}
      icon={<ShieldIcon size={16} className="fgColor-onEmphasis" />}
      actionText="opened this alert"
      badgeClassName="bgColor-success-emphasis"
      data-testid="timeline-event-opened"
    >
      {openedInfo && (
        <span className="color-fg-muted ml-1">
          on {openedInfo.package_name} {openedInfo.package_version}
        </span>
      )}
    </TimelineEventWithActor>
  )
}

try{ OpenedEvent.displayName ||= 'OpenedEvent' } catch {}