import {LawIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'
import type {AlertEvent, LicensesAddedEventBody} from '../../../types/alerts'
import {TimelineEventWithActor, parseEventBody} from './shared'

interface LicensesAddedEventProps {
  event: AlertEvent
  repoLicensePolicyPath?: string
  repoName?: string
}

export function LicensesAddedEvent({event, repoLicensePolicyPath, repoName}: LicensesAddedEventProps) {
  const licensesInfo = parseEventBody<LicensesAddedEventBody>(event.eventBody)

  return (
    <TimelineEventWithActor
      event={event}
      icon={<LawIcon size={16} />}
      actionText={
        licensesInfo?.licenses && Array.isArray(licensesInfo.licenses) ? (
          <>
            added {licensesInfo.licenses.join(', ')}
            {repoLicensePolicyPath && (
              <>
                {' to '}
                <Link muted href={repoLicensePolicyPath} data-testid="policy-link">
                  {/* Distributed policy hardcoded but we need to pass from alert in future*/}
                  Distributed policy
                </Link>
              </>
            )}
            {repoName && <span data-testid="repo-name"> for {repoName}</span>}
          </>
        ) : (
          'added to approved licenses'
        )
      }
      data-testid="timeline-event-licenses-added"
    />
  )
}

try{ LicensesAddedEvent.displayName ||= 'LicensesAddedEvent' } catch {}