import {Stack, Token} from '@primer/react'
import {ShieldIcon, ShieldCheckIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import styles from './LicenseComplianceAlertStatus.module.css'
import {type Alert, AlertStatus} from '../types/alerts'
import {formatAlertStatus} from '../helpers/formatters'

export interface LicenseComplianceAlertStatusProps {
  createdAt: Alert['createdAt']
  manifestName: Alert['manifestName']
  packageEcosystem: Alert['packageEcosystem']
  packageName: Alert['packageName']
  status: Alert['status']
}

export function LicenseComplianceAlertStatus({
  createdAt,
  manifestName,
  packageEcosystem,
  packageName,
  status,
}: LicenseComplianceAlertStatusProps) {
  const renderStatusTag = () => {
    let icon = <ShieldIcon className="fgColor-onEmphasis" />
    let tokenClassName = styles.statusTokenOpen

    if (status === AlertStatus.Closed) {
      icon = <ShieldCheckIcon className="fgColor-onEmphasis" />
      tokenClassName = styles.statusTokenClosed
    }

    return (
      <Token
        text={<span className="fgColor-onEmphasis">{formatAlertStatus(status)}</span>}
        size="xlarge"
        leadingVisual={() => icon}
        className={tokenClassName}
      />
    )
  }

  return (
    <Stack data-testid="license-compliance-alert-status" direction="horizontal" align="center" gap="condensed">
      {renderStatusTag()}
      <span className={clsx('fgColor-muted', styles.statusDescription)}>
        {`Opened on ${createdAt} on `}
        <span className="text-bold">{packageName}</span>
        {` (${packageEcosystem}) · ${manifestName}`}
      </span>
    </Stack>
  )
}

try{ LicenseComplianceAlertStatus.displayName ||= 'LicenseComplianceAlertStatus' } catch {}