import pluralize from 'pluralize'
import parse from 'spdx-expression-parse'

interface SpdxNode {
  license?: string
  left?: SpdxNode | string
  right?: SpdxNode | string
}

function getAddLicenseDescription(expressions: string[]): string {
  let licensesToMention = ''

  if (expressions.length === 2) {
    licensesToMention = `${expressions.join(' and ')} `
  } else if (expressions.length > 2) {
    licensesToMention = `${expressions.slice(0, 2).join(', ')} and ${pluralize('other', expressions.length - 2)} `
  }

  return `Add ${licensesToMention}to allowed licenses`
}

export function getSpdxSummary(licenseString: string): {label: string; description: string} {
  if (!licenseString) {
    return {
      label: 'No license detected',
      description: 'Cannot add "no license" to allowed list',
    }
  }

  const expressions = parseSpdxExpressions(licenseString)

  return {
    label: expressions.length === 1 ? (expressions[0] as string) : 'Add to allowed licenses',
    description: getAddLicenseDescription(expressions),
  }
}

/**
 * Parses a license string and returns all SPDX expressions found in the string.
 * @param licenseString - The license expression string to parse
 * @returns An array of SPDX expressions found in the license string
 */
export function parseSpdxExpressions(licenseString: string): string[] {
  try {
    const parsed = parse(licenseString)

    return extractExpressions(parsed)
  } catch {
    return []
  }
}

/**
 * Recursively extracts all license expressions from a parsed SPDX object
 */
function extractExpressions(node: SpdxNode | string): string[] {
  if (typeof node === 'string') {
    return [node]
  }

  if (node.license) {
    return [node.license]
  }

  if (node.left && node.right) {
    return [...extractExpressions(node.left), ...extractExpressions(node.right)]
  }

  if (node.left) {
    return extractExpressions(node.left)
  }

  if (node.right) {
    return extractExpressions(node.right)
  }

  return []
}
