import {Timeline} from '@primer/react'
import {TimelineEventItem} from './TimelineEventItem'
import type {AlertEvent} from '../../types/alerts'

interface AlertTimelineProps {
  events: AlertEvent[]
  onReviewRequest?: () => void
  repoLicensePolicyPath?: string
  repoName?: string
}

export function AlertTimeline({events, onReviewRequest, repoLicensePolicyPath, repoName}: AlertTimelineProps) {
  if (!events || events.length === 0) {
    return null
  }

  return (
    <Timeline data-testid="alert-timeline">
      {events.map(event => (
        <TimelineEventItem
          key={event.id}
          event={event}
          onReviewRequest={onReviewRequest}
          repoLicensePolicyPath={repoLicensePolicyPath}
          repoName={repoName}
        />
      ))}
    </Timeline>
  )
}

try{ AlertTimeline.displayName ||= 'AlertTimeline' } catch {}