import {mainQuery} from '@github-ui/react-core/future/main-query'
import {licenseComplianceAlertsAppBuilder} from '../config/app-builder'
import type {Alert} from '../types/alerts'

export type LicenseComplianceAlertsResponse = {
  enterpriseName: string
  enterpriseId: number
  alerts: Alert[]
}

export const licenseComplianceAlertsRoute = licenseComplianceAlertsAppBuilder.createQueryRouteConfig(
  'licenseComplianceAlertsRoute',
  {
    path: '/enterprises/:enterprise/security/bypass-requests/license-compliance',
    queries: [mainQuery<LicenseComplianceAlertsResponse>()],
  },
)
